package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeNumber(short i)
 */
public class TokenBuffer_writeNumber_TriageGen2Test {

    private TokenBuffer tokenBuffer;
    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteNumber_PositiveShort() throws IOException {
        short value = 123;
        tokenBuffer.writeNumber(value);

        // Verify the content by converting to a parser and checking tokens
        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        assertEquals(123, parser.getIntValue());
    }

    @Test
    public void testWriteNumber_NegativeShort() throws IOException {
        short value = -456;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        assertEquals(-456, parser.getIntValue());
    }

    @Test
    public void testWriteNumber_MaxShort() throws IOException {
        short value = Short.MAX_VALUE;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        assertEquals(Short.MAX_VALUE, parser.getIntValue());
    }

    @Test
    public void testWriteNumber_MinShort() throws IOException {
        short value = Short.MIN_VALUE;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        assertEquals(Short.MIN_VALUE, parser.getIntValue());
    }

    @Test
    public void testWriteNumber_Zero() throws IOException {
        short value = 0;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        assertEquals(0, parser.getIntValue());
    }

    @Test
    public void testWriteNumber_SequentialCalls() throws IOException {
        tokenBuffer.writeStartObject();
        tokenBuffer.writeFieldName("first");
        tokenBuffer.writeNumber((short) 10);
        tokenBuffer.writeFieldName("second");
        tokenBuffer.writeNumber((short) 20);
        tokenBuffer.writeEndObject();

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        assertEquals("first", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(10, parser.getIntValue());

        assertEquals("second", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(20, parser.getIntValue());

        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }
}
